-- DevMind portable schema.
--
-- Constraints on purpose, so the *same* file works in SQLite-WASM inside the
-- PWA and in CPython on the home PC:
--   * no AUTOINCREMENT, no STRICT tables, no generated columns
--   * ids are TEXT generated by the client
--   * timestamps are REAL unix seconds
--   * FTS5 is NOT part of the schema; it is created opportunistically by the
--     host (some WASM builds omit it) and retrieval degrades to vector search.
-- Everything is CREATE IF NOT EXISTS so an old database upgrades in place.

CREATE TABLE IF NOT EXISTS memories (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL,
    text TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT 'local',
    created_at REAL NOT NULL,
    updated_at REAL NOT NULL,
    weight REAL NOT NULL DEFAULT 1.0,
    meta TEXT NOT NULL DEFAULT '{}',
    embedding BLOB
);
CREATE INDEX IF NOT EXISTS idx_memories_kind ON memories(kind);
CREATE INDEX IF NOT EXISTS idx_memories_created ON memories(created_at DESC);

CREATE TABLE IF NOT EXISTS episodes (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    role TEXT NOT NULL,
    content TEXT NOT NULL,
    created_at REAL NOT NULL,
    meta TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_episodes_session ON episodes(session_id, created_at DESC);

CREATE TABLE IF NOT EXISTS feedback (
    id TEXT PRIMARY KEY,
    answer_id TEXT,
    rating INTEGER NOT NULL,
    task TEXT,
    model TEXT,
    correction TEXT,
    created_at REAL NOT NULL
);

CREATE TABLE IF NOT EXISTS model_stats (
    task TEXT NOT NULL,
    model TEXT NOT NULL,
    alpha REAL NOT NULL DEFAULT 1.0,
    beta REAL NOT NULL DEFAULT 1.0,
    runs INTEGER NOT NULL DEFAULT 0,
    wins INTEGER NOT NULL DEFAULT 0,
    latency_ema REAL NOT NULL DEFAULT 0.0,
    updated_at REAL NOT NULL,
    PRIMARY KEY (task, model)
);

CREATE TABLE IF NOT EXISTS routing_log (
    id TEXT PRIMARY KEY,
    at REAL NOT NULL,
    session TEXT,
    task TEXT,
    language TEXT,
    difficulty REAL,
    model TEXT,
    reason TEXT,
    prompt_chars INTEGER,
    outcome TEXT
);

CREATE TABLE IF NOT EXISTS skills (
    name TEXT PRIMARY KEY,
    description TEXT NOT NULL DEFAULT '',
    steps TEXT NOT NULL DEFAULT '[]',
    successes INTEGER NOT NULL DEFAULT 0,
    failures INTEGER NOT NULL DEFAULT 0,
    updated_at REAL NOT NULL
);

CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

-- ---------------------------------------------------------------------------
-- Code index
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS code_files (
    repo TEXT NOT NULL,
    path TEXT NOT NULL,
    sha TEXT NOT NULL,
    lang TEXT NOT NULL DEFAULT 'unknown',
    size INTEGER NOT NULL DEFAULT 0,
    mtime REAL NOT NULL DEFAULT 0,
    indexed_at REAL NOT NULL,
    PRIMARY KEY (repo, path)
);

CREATE TABLE IF NOT EXISTS code_chunks (
    id TEXT PRIMARY KEY,
    repo TEXT NOT NULL,
    path TEXT NOT NULL,
    start_line INTEGER NOT NULL,
    end_line INTEGER NOT NULL,
    kind TEXT NOT NULL DEFAULT 'block',
    symbol TEXT NOT NULL DEFAULT '',
    text TEXT NOT NULL,
    sha TEXT NOT NULL,
    embedding BLOB
);
CREATE INDEX IF NOT EXISTS idx_code_chunks_repo ON code_chunks(repo);
CREATE INDEX IF NOT EXISTS idx_code_chunks_path ON code_chunks(repo, path);

CREATE TABLE IF NOT EXISTS code_symbols (
    id TEXT PRIMARY KEY,
    repo TEXT NOT NULL,
    path TEXT NOT NULL,
    name TEXT NOT NULL,
    kind TEXT NOT NULL DEFAULT 'symbol',
    line INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_code_symbols_repo ON code_symbols(repo);
CREATE INDEX IF NOT EXISTS idx_code_symbols_name ON code_symbols(repo, name);

CREATE TABLE IF NOT EXISTS index_state (
    repo TEXT PRIMARY KEY,
    root TEXT NOT NULL,
    updated_at REAL NOT NULL,
    complete INTEGER NOT NULL DEFAULT 0
);
